"""Checkout pricing with provisional expired-promotion handling.

PROVISIONAL: product has not decided what happens with an expired promotion.
Current choice: require customer confirmation, then proceed at full price.
Change EXPIRED_PROMO_POLICY to switch behaviour.
"""
from dataclasses import dataclass
from datetime import datetime
from typing import Optional

EXPIRED_PROMO_POLICY = "confirm"  # "confirm" | "reject" | "ignore"


@dataclass
class Promotion:
    code: str
    percent_off: int
    expires_at: datetime


@dataclass
class CheckoutResult:
    status: str  # "ok" | "needs_confirmation" | "rejected"
    total: Optional[float] = None
    message: str = ""


def checkout(subtotal: float, promo: Optional[Promotion], now: datetime,
             confirmed_without_promo: bool = False) -> CheckoutResult:
    if promo is None:
        return CheckoutResult("ok", round(subtotal, 2))
    if now <= promo.expires_at:
        return CheckoutResult("ok", round(subtotal * (100 - promo.percent_off) / 100, 2))

    msg = f"Promotion {promo.code} has expired."
    if EXPIRED_PROMO_POLICY == "reject":
        return CheckoutResult("rejected", None, msg)
    if EXPIRED_PROMO_POLICY == "ignore" or confirmed_without_promo:
        return CheckoutResult("ok", round(subtotal, 2), msg + " Charged full price.")
    return CheckoutResult("needs_confirmation", round(subtotal, 2),
                          msg + " Continue at full price?")
E
cat > test_checkout.py <<'E'
from datetime import datetime, timedelta
import checkout
from checkout import Promotion, checkout as run

NOW = datetime(2026, 11, 22)
VALID = Promotion("SAVE10", 10, NOW + timedelta(days=1))
EXPIRED = Promotion("OLD10", 10, NOW - timedelta(days=1))


def test_no_promo():
    assert run(100, None, NOW).total == 100

def test_valid_promo_applies():
    assert run(100, VALID, NOW).total == 90

def test_expired_requires_confirmation():
    r = run(100, EXPIRED, NOW)
    assert r.status == "needs_confirmation" and r.total == 100

def test_expired_confirmed_charges_full_price():
    r = run(100, EXPIRED, NOW, confirmed_without_promo=True)
    assert r.status == "ok" and r.total == 100

def test_alternative_policies(monkeypatch):
    monkeypatch.setattr(checkout, "EXPIRED_PROMO_POLICY", "reject")
    assert run(100, EXPIRED, NOW).status == "rejected"
    monkeypatch.setattr(checkout, "EXPIRED_PROMO_POLICY", "ignore")
    assert run(100, EXPIRED, NOW).status == "ok"
E
